fn update(scene: &mut GameScene<'_>, _time: &FrameTime) {
    if !scene.pressed("reset") {
        return;
    }
    let names = (1..=9)
        .map(|index| format!("Box {index}"))
        .chain((1..=2).map(|index| format!("Ball {index}")));
    for name in names {
        let Some(start) = scene.initial(&name) else {
            continue;
        };
        scene
            .object(&name)
            .set_position(start.transform.position)
            .set_rotation(start.transform.rotation);
        scene.reset_body(&name);
    }
    scene.add_to_counter("resets", 1);
}
